// Simplified linker symbol resolution
void link(ObjectFile** inputs, int n) {
    SymbolTable global;

    for (int i = 0; i < n; i++) {
        ObjectFile* obj = inputs[i];

        // Add definitions
        for (Symbol* sym = obj->exports; sym; sym = sym->next) {
            if (lookup(global, sym->name)) {
                error("Duplicate symbol: %s", sym->name);
            }
            insert(global, sym->name, sym->value);
        }

        // Resolve references
        for (Reloc* rel = obj->relocs; rel; rel = rel->next) {
            Symbol* def = lookup(global, rel->symbol);
            if (!def) {
                error("Undefined reference: %s", rel->symbol);
            }
            // Patch the reference
            patch(obj, rel->offset, def->value + rel->addend);
        }
    }
}
